    }
  },
  "audit_selection": {
    "initial_free_text_need": "Before ID selection, the recipient requested evidence for: (1) the reconciliation-key implementation plus the multi-subscription same-customer fixture/test/output showing whether two subscriptions on the same report date produce distinct keys/records and distinguish billing periods; and (2) the page-2 HTTP 429 retry/fallback path and the 37-record snapshot use, including freshness validation, stale marking, idempotency handling, and whether authoritative API state was later confirmed.",
    "selected_items": [
      {
        "id": "SH2-R2",
        "relevance": "strong",
        "basis": "It directly targets the initial live uncertainty about the 37 snapshot-sourced page-2 records: freshness verification, provenance, stale marking, and silent substitution."
      },
      {
        "id": "SH2-R3",
        "relevance": "partial",
        "basis": "It directly targets the helper definition, but the initial stated need also included test/fixture/output evidence showing multi-subscription behavior; SH2-R3 alone does not supply that."
      }
    ],
    "unnecessary_requests": [],
